BG=colors.HexColor('#09090F'); SURFACE=colors.HexColor('#14111D'); PLUM=colors.HexColor('#211831'); VIOLET=colors.HexColor('#7C3AED'); GOLD=colors.HexColor('#D6B479'); IVORY=colors.HexColor('#F7F2FF'); MUTED=colors.HexColor('#B6A8C6'); BORDER=colors.HexColor('#392B4C')

TOPICS=[
('TypeScript Foundations and Strict Mode','TypeScript statically analyzes JavaScript and erases types before runtime. Strict mode catches uncertain nulls, implicit any, unsafe indexed access, and incompatible functions earlier, but compilation never validates network payloads or environment values.','Enable strict settings for new code; migrate legacy code in measured stages; accept unknown at untrusted boundaries; compile application and test sources in CI.','Assuming compilation validates runtime data; using any to silence migration errors; mixing browser and server libraries in one permissive configuration.','Create a strict tsconfig and justify target, module, lib, noUncheckedIndexedAccess, and exactOptionalPropertyTypes.',['SOURCE','TYPE CHECK','EMIT JS','RUNTIME'],"function formatName(value: unknown): string {\n  if (typeof value !== 'string') throw new TypeError('name');\n  return value.trim();\n}"),
('Types versus Interfaces','Interfaces name object contracts and support declaration merging. Type aliases name any type expression, including unions, tuples, primitives, and mapped types. Both describe object shapes. Choose based on openness and composition, not myths about universal superiority.','Use interfaces for intentionally extensible object contracts; use aliases for unions and computed types; export narrow public contracts; separate persistence records from API DTOs.','Depending on accidental declaration merging; exporting database shapes; intersecting incompatible properties.','Model a public user without exposing email, password hashes, or storage metadata.',['DOMAIN','INTERNAL','PROJECTION','PUBLIC DTO'],"interface UserRecord { id: string; email: string; role: Role }\ntype Role = 'member' | 'admin';\ntype PublicUser = Pick<UserRecord, 'id' | 'role'>;"),
('Unions, Intersections, and Discriminated Unions','A union represents alternatives. A stable discriminant lets control flow narrow safely and makes contradictory state difficult to construct. Intersections require every member and can collapse conflicting properties to never.','Give variants one discriminant; keep variant-only data inside its branch; use assertNever for exhaustive switches; prefer state machines to clusters of booleans.','Making every state field optional; casting after an incomplete switch; intersecting conflicting contracts.','Model pending, paid, and failed payment display states without isPaid and hasError flags.',['UNION','DISCRIMINANT','NARROW','EXHAUSTIVE'],"type PaymentState =\n | { kind: 'pending'; createdAt: Date }\n | { kind: 'paid'; paymentId: string }\n | { kind: 'failed'; reason: string };"),
('Generics and Constraints','Generics preserve relationships between values. Constraints state the minimum capability an algorithm needs while retaining the caller’s more specific type. Useful generics reduce duplication; decorative type parameters only move complexity.','Introduce parameters only for meaningful relationships; constrain the smallest required shape; prefer readonly inputs; test inference at call sites.','Returning T after constructing something that is not T; unconstrained property access; abstracting a single call site.','Write a lookup accepting any readonly collection whose items have string IDs.',['CALLER TYPE','CONSTRAINT','ALGORITHM','PRESERVED TYPE'],"function firstById<T extends { id: string }>(items: readonly T[], id: string): T | undefined {\n  return items.find(item => item.id === id);\n}"),
('Utility Types and Mapped Types','Pick, Omit, Partial, Required, Readonly, and Record derive useful views of existing contracts. Mapped types encode systematic transformations. Partial is shallow, Readonly is compile-time only, and complex conditional types can become harder to maintain than explicit contracts.','Derive projections from authoritative types; use dedicated create and update inputs; name advanced utilities; document business meaning outside type mechanics.','Using Partial Entity as an unrestricted patch; assuming Readonly freezes objects; hiding rules in unreadable conditional types.','Design create, patch, stored, and public forms of an account.',['DOMAIN','PICK/OMIT','MAPPED','BOUNDARY'],"type MutablePatch<T> = { -readonly [K in keyof T]?: T[K] };"),
('Domain Modeling','Domain types represent business meaning rather than database columns. Entity identity persists while attributes change; value objects centralize invariants. Branded IDs reduce accidental mixing but still require runtime construction and validation.','Name types with business language; make invalid states hard to construct; separate persistence documents; validate primitive input before domain admission.','Using string for every identifier; embedding HTTP concerns in entities; treating brands as runtime validation.','Model an Order whose paid transition requires a verified payment reference.',['EXTERNAL','VALIDATE','DOMAIN','INVARIANT'],"type OrderId = string & { readonly __brand: 'OrderId' };\ntype PaidOrder = { id: OrderId; state: 'paid'; paymentId: string };"),
('Clean Architecture and Dependency Boundaries','Dependencies should point toward stable policy. Domain code does not import frameworks, databases, or HTTP objects. Application services coordinate use cases through ports; adapters implement those ports with Mongoose, fetch, storage, or SDKs.','Keep business rules framework independent; define ports at consumption points; construct adapters at the composition root; pass verified identity and validated inputs.','Creating interfaces for every helper; leaking ORM documents; importing server secrets into client code.','Draw checkout dependencies across an order service, repository, payment gateway, and entitlement port.',['UI/API','APPLICATION','DOMAIN','PORT','ADAPTER'],"interface UserRepository {\n  findById(id: string): Promise<UserRecord | null>;\n}"),
('API Request and Response Contracts','An API contract includes payload, status semantics, error vocabulary, authorization, and compatibility. Shared TypeScript types improve producer consistency but cannot validate bytes received over a network. DTOs should be explicit and minimal.','Validate request bodies; return stable error codes; model expected failures; review generated public documentation.','Returning 200 for every outcome; exposing internal errors; sending persistence models directly.','Define create-user success, validation, conflict, and unauthorized responses.',['UNKNOWN BODY','VALIDATE','DTO','USE CASE','RESPONSE'],"type ApiResponse<T> =\n | { status: 200; data: T }\n | { status: 400 | 401 | 403 | 404; error: { code: string; message: string } };"),
('Runtime Validation and Type Safety','Network bodies, environment variables, parsed JSON, storage, and migrated database rows are untrusted. Runtime validation converts unknown into a trusted input or structured issues. A type assertion performs no check.','Accept unknown at boundaries; validate shapes, ranges, formats, and cross-field rules; sanitize error responses; infer types from reviewed schemas when available.','Casting request JSON; validating only in the browser; silently coercing malformed data.','Validate email input across non-object, missing, wrong-type, and malformed values.',['UNKNOWN','SHAPE','FIELD RULES','TRUSTED'],"function isCreateUserInput(value: unknown): value is { email: string } {\n  if (typeof value !== 'object' || value === null) return false;\n  const input = value as Record<string, unknown>;\n  return typeof input.email === 'string' && input.email.includes('@');\n}"),
('Error Modeling and Result Patterns','Exceptions suit unexpected failures and rejection-based boundaries. Result unions make expected business failures explicit and force narrowing. Public codes stay stable and safe while server logs may preserve private diagnostic causes.','Separate expected outcomes from defects; preserve causes internally; translate infrastructure failures; exhaustively handle stable error unions.','Returning undefined without context; exposing provider messages; building one enormous global error union.','Model configuration parsing with missing and invalid outcomes.',['OPERATION','OK','EXPECTED ERROR','MAP'],"type Result<T,E> = { ok: true; value: T } | { ok: false; error: E };"),
('Repository and Service Patterns','Repositories expose persistence needed by use cases, not every conceivable query. Services coordinate domain rules, authorization, repositories, and external ports. Transactions protect invariants that must commit together.','Return domain values or DTOs; keep queries use-case oriented; inject ports for tests; state transaction boundaries.','Generic repository dumping grounds; UI-only authorization; holding transactions during remote calls.','Implement getPublicUser through a repository and an explicit not-found Result.',['SERVICE','REPOSITORY','ADAPTER','DTO'],"class UserService {\n constructor(private readonly users: UserRepository) {}\n async getPublicUser(id: string): Promise<Result<PublicUser,'not_found'>> {\n  const user = await this.users.findById(id);\n  return user ? { ok: true, value: toPublicUser(user) } : { ok: false, error: 'not_found' };\n }\n}"),
('Configuration and Environment Validation','Environment variables are optional strings, not typed configuration. Parse them once in a server-only module, validate presence and range, reject forbidden operational modes, and expose a minimal immutable object.','Fail fast for required settings; redact secrets; separate public and private settings; validate mode and credential prefixes together.','Non-null assertions on process.env; public-prefixed secrets; numbers parsed without bounds.','Parse PORT and a test-only payment key without serializing either to clients.',['PROCESS ENV','VALIDATOR','CONFIG','SERVER'],"function parsePort(value: string | undefined): Result<number,'missing'|'invalid'> {\n if (!value) return { ok: false, error: 'missing' };\n const port = Number(value);\n return Number.isInteger(port) && port > 0 && port <= 65535\n  ? { ok: true, value: port } : { ok: false, error: 'invalid' };\n}"),
('Authentication and Authorization Boundaries','Authentication establishes identity; authorization decides whether that identity can act on a resource. Identity must come from a verified server session. Browser-supplied user IDs, roles, paid flags, and ownership claims are data, not authority.','Authenticate personalized entry points; authorize ownership from server records; fail closed on missing role configuration; protect pages, APIs, and actions independently.','Hiding links without protecting routes; trusting form ownership; treating authentication as authorization.','Specify private download authorization using session, paid order, entitlement, active asset, and rate limit.',['SESSION','RESOURCE','OWNERSHIP','POLICY','ALLOW'],"function requireRole(user: Pick<UserRecord,'role'>, role: Role) {\n return user.role === role ? { ok: true as const, value: true as const }\n  : { ok: false as const, error: 'forbidden' as const };\n}"),
('Async Programming and Error Handling','Promises represent eventual completion, not cancellation or automatic retry. Catch errors only where context, recovery, or translation is possible. Use AbortSignal where supported and retry only bounded, transient, idempotent operations.','Set remote timeouts; propagate cancellation; parallelize independent work deliberately; define partial-result policy.','Blind non-idempotent retries; swallowed errors; unnecessary sequential awaits.','Fetch three independent resources with a timeout and define whether one failure cancels all.',['START','PROMISE','AWAIT','RESULT','CLEANUP'],"async function settle<T>(operation: () => Promise<T>): Promise<Result<T,Error>> {\n try { return { ok: true, value: await operation() }; }\n catch (cause) { return { ok: false, error: cause instanceof Error ? cause : new Error('Unknown') }; }\n}"),
('Testing Typed Applications','Type checking and runtime tests catch different defects. Unit tests verify behavior, integration tests verify adapters, contract tests verify compatibility, and end-to-end tests verify real flows. Negative paths and authorization deserve first-class coverage.','Compile production and tests strictly; test malformed unknown input; fake ports in unit tests; integration-test real adapters; assert idempotency.','Believing types replace tests; mocking the subject; snapshotting unstable objects.','Test service success, not-found, and repository failure without production data.',['TYPECHECK','UNIT','INTEGRATION','CONTRACT','E2E'],"it('returns a public projection', async () => {\n const service = new UserService(fakeRepository);\n await expect(service.getPublicUser('u1')).resolves.toEqual({\n  ok: true, value: { id: 'u1', role: 'member' }\n });\n});"),
('TypeScript with Next.js','App Router Server Components may use server resources; Client Components are a browser boundary and require serializable props. Route handlers validate Request input and derive identity server-side. Installed framework types remain the authority for version-specific signatures.','Keep database modules server-only; pass minimal DTOs to clients; validate route parameters; authorize again at protected operations.','Importing models into client components; passing Mongoose documents; assuming middleware replaces endpoint checks.','Design a server product page with a minimal bookmark client island.',['REQUEST','SERVER','DTO','CLIENT'],"type ProductPageProps = { params: Promise<{ slug: string }> };\nasync function readSlug(props: ProductPageProps) {\n return (await props.params).slug;\n}"),
('Security and Performance Considerations','Types do not sanitize HTML, prevent injection, authorize users, or hide secrets. Validate and encode boundaries, parameterize queries, minimize client data, and measure before optimizing. Excessively recursive types can also degrade compiler and editor performance.','Use safe rendering; project minimum fields; redact secrets and paths; measure bundles, queries, and compiler diagnostics.','Naming values SafeHtml without sanitization; returning complete records; premature type complexity.','Review one endpoint for injection, over-fetching, ownership, leakage, caching, and rate limiting.',['UNTRUSTED','VALIDATE','AUTHORIZE','MINIMAL','OBSERVE'],"function toPublicUser(user: UserRecord): PublicUser {\n return { id: user.id, role: user.role };\n}"),
('Refactoring JavaScript to TypeScript','Migrate stable boundaries incrementally. Establish a strict destination, type external inputs as unknown, describe important domain contracts, and shrink any over time. Characterization tests preserve runtime behavior before redesign.','Start with leaf utilities; add tests before changing ambiguous behavior; replace any with unknown plus validation; track temporary exceptions.','Automated casts to silence errors; redesigning everything during migration; declarations that misdescribe runtime behavior.','Migrate a JavaScript user parser through tests, unknown input, validation, and Result.',['JS TESTS','RENAME','UNKNOWN','VALIDATE','REMOVE ANY'],"function parseLegacyUser(value: unknown): Result<UserRecord,'invalid_user'> {\n if (!isCreateUserInput(value)) return { ok: false, error: 'invalid_user' };\n return validateIdentityAndRole(value);\n}"),
('Practical Case Studies','A checkout system separates pricing, payment, orders, and entitlements; payment state comes only from verified provider data. A private download joins server identity, paid order, entitlement, active asset, storage, and audit activity. An API migration validates unknown values before domain construction.','Draw trust and transaction boundaries; keep provider payloads outside the domain until verified; use conditional idempotent updates; test replay and partial failure.','Letting redirects mark payments paid; provisioning before verification; asserting provider payload types.','Design ports for checkout creation, confirmation, entitlement provisioning, and download authorization.',['HTTP','APPLICATION','DOMAIN','ADAPTERS','AUDIT'],"function uniqueById<T extends { id: string }>(items: readonly T[]): T[] {\n return [...new Map(items.map(item => [item.id, item])).values()];\n}"),
('Interview Questions and Revision Notes','Prepare to explain structural typing, unknown versus any, narrowing, never, generic constraints, mapped types, runtime validation, dependency inversion, DTOs, Result patterns, authorization, cancellation, and why compilation and testing are complementary. Strong answers name boundaries and trade-offs.','State runtime limitations; demonstrate narrowing; explain when abstraction is unnecessary; connect architecture to security and testability.','Claiming interfaces exist at runtime; saying aliases cannot describe objects; treating architecture as folder names.','Explain how untrusted provider data becomes a verified paid Order without trusting redirects.',['QUESTION','ASSUMPTIONS','MODEL','TRADE-OFF','VERIFY'],"// unknown -> validate -> domain type -> authorized use case\n// -> minimal response. Types support boundaries but replace none."),
]

class Flow(Flowable):
 def __init__(self,labels):super().__init__();self.labels=labels;self.width=170*mm;self.height=22*mm
 def draw(self):
  c=self.canv;n=len(self.labels);gap=3*mm;w=(self.width-gap*(n-1))/n
  for i,label in enumerate(self.labels):
   x=i*(w+gap);c.setFillColor(PLUM);c.setStrokeColor(VIOLET);c.roundRect(x,4*mm,w,12*mm,2*mm,fill=1,stroke=1);c.setFillColor(IVORY);c.setFont('Helvetica-Bold',6);c.drawCentredString(x+w/2,9.5*mm,label[:18])
   if i<n-1:c.setStrokeColor(GOLD);c.line(x+w,10*mm,x+w+gap,10*mm)

class Doc(BaseDocTemplate):
 def __init__(self,filename,**kw):super().__init__(filename,**kw);self.addPageTemplates(PageTemplate(id='main',frames=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='f'),onPage=self.art))
 def art(self,c,doc):
  c.saveState();c.setFillColor(BG);c.rect(0,0,A4[0],A4[1],fill=1,stroke=0);c.setStrokeColor(BORDER);c.line(20*mm,15*mm,A4[0]-20*mm,15*mm);c.setFillColor(MUTED);c.setFont('Helvetica',8);c.drawString(20*mm,9*mm,'DevVault  |  TypeScript Systems Blueprint');c.drawRightString(A4[0]-20*mm,9*mm,str(doc.page));c.restoreState()
 def afterFlowable(self,f):
  if isinstance(f,Paragraph) and f.style.name in ('Chapter','H2'):
   level=0 if f.style.name=='Chapter' else 1;text=f.getPlainText();key=f'h{level}-{self.seq.nextf("h")}';self.canv.bookmarkPage(key);self.canv.addOutlineEntry(text,key,level=level,closed=False);self.notify('TOCEntry',(level,text,self.page,key))

def styles():
 s=getSampleStyleSheet();return {'title':ParagraphStyle('TitleLuxe',parent=s['Title'],fontName='Helvetica-Bold',fontSize=29,leading=34,textColor=IVORY,spaceAfter=9*mm),'sub':ParagraphStyle('Sub',parent=s['Normal'],fontSize=12.5,leading=19,textColor=MUTED,spaceAfter=7*mm),'chapter':ParagraphStyle('Chapter',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=20.5,leading=25,textColor=IVORY,spaceAfter=4*mm),'h2':ParagraphStyle('H2',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=13.2,leading=17,textColor=GOLD,spaceBefore=3*mm,spaceAfter=1.5*mm),'body':ParagraphStyle('Body',parent=s['BodyText'],fontSize=9.5,leading=13.4,textColor=IVORY,spaceAfter=2.3*mm),'small':ParagraphStyle('Small',parent=s['BodyText'],fontSize=8.3,leading=11.5,textColor=MUTED),'bullet':ParagraphStyle('BulletLuxe',parent=s['BodyText'],fontSize=9,leading=12.4,textColor=IVORY,leftIndent=5*mm,firstLineIndent=-3*mm,spaceAfter=1*mm),'code':ParagraphStyle('Code',fontName='Courier',fontSize=6.4,leading=8.1,textColor=colors.HexColor('#D9E6FF'),leftIndent=3*mm,rightIndent=3*mm,spaceBefore=1.5*mm,spaceAfter=2*mm,backColor=SURFACE,borderColor=BORDER,borderWidth=.5,borderPadding=5),'toc0':ParagraphStyle('TOC0',fontName='Helvetica-Bold',fontSize=10,leading=15,textColor=IVORY),'toc1':ParagraphStyle('TOC1',fontName='Helvetica',fontSize=8.5,leading=12,textColor=MUTED,leftIndent=8*mm)}

def bullet(text,s):return Paragraph(f"<font color='#D6B479'>•</font> {html.escape(text)}",s['bullet'])
def code_block(code,s):
 value=html.escape(code).replace(' ','&nbsp;');value=re.sub(r'\b(type|interface|function|class|return|const|let|async|await|extends|readonly|new|throw|if|else|switch|case|default)\b',r"<font color='#C4A7FF'><b>\1</b></font>",value);return Paragraph(value.replace('\n','<br/>'),s['code'])

def cover(s,sample):
 label='PUBLIC SAMPLE' if sample else 'PROFESSIONAL ARCHITECTURE GUIDE';return [Spacer(1,27*mm),Paragraph('TYPESCRIPT SYSTEMS<br/>BLUEPRINT',s['title']),Paragraph('Strict types, trustworthy boundaries, domain modeling, and maintainable application architecture',s['sub']),Spacer(1,10*mm),Table([[label],['DevVault Educational Series'],['Twenty practical chapters with compiled TypeScript patterns'],['Edition 1.0  |  October 2026']],colWidths=[160*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,0),VIOLET),('BACKGROUND',(0,1),(-1,-1),PLUM),('TEXTCOLOR',(0,0),(-1,-1),IVORY),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('BOX',(0,0),(-1,-1),1,BORDER),('INNERGRID',(0,0),(-1,-1),.25,BORDER),('LEFTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)])),Spacer(1,10*mm),Paragraph('Original educational material. TypeScript examples are validated by the repository compiler; selected behaviors are executed with Vitest. Types do not replace runtime validation, authorization, testing, or operational evidence.',s['small']),PageBreak()]

def chapter(item,n,s):
 title,explain,guidance,mistakes,exercise,diagram,code=item;out=[Paragraph(f'{n:02d}  {title}',s['chapter']),Paragraph(explain,s['body']),Paragraph('System boundary',s['h2']),Flow(diagram),Paragraph('Production guidance',s['h2'])]+[bullet(x,s) for x in guidance.split(';')]
 out += [Paragraph('Typed example',s['h2']),code_block(code,s),Paragraph('Common mistakes',s['h2'])]+[bullet(x,s) for x in mistakes.split(';')]
 out += [Paragraph('Hands-on exercise',s['h2']),Table([[Paragraph(exercise,s['body'])]],colWidths=[165*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,-1),PLUM),('BOX',(0,0),(-1,-1),1,GOLD),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)])),PageBreak()];return out

def build(path,sample=False):
 s=styles();story=cover(s,sample)
 if sample:
  story += [Paragraph('What this sample includes',s['chapter']),Paragraph('This limited sample contains three introductory chapters. It demonstrates the complete guide’s editorial style, type examples, system diagrams, mistakes, and exercises without exposing the remaining seventeen chapters or case-study material.',s['body']),PageBreak()]
  for i,item in enumerate(TOPICS[:3],1):story += chapter(item,i,s)
  story += [Paragraph('Continue with the complete blueprint',s['chapter']),Paragraph('The paid guide continues through generics, domain modeling, architecture, API validation, errors, repositories, configuration, authorization, asynchronous work, testing, Next.js, security, migration, case studies, and interview revision.',s['body'])]
 else:
  story += [Paragraph('Contents',s['chapter'])];toc=TableOfContents();toc.levelStyles=[s['toc0'],s['toc1']];story += [toc,PageBreak(),Paragraph('How to use this blueprint',s['chapter']),Paragraph('Chapters 1–5 establish language tools. Chapters 6–14 apply them to trustworthy application boundaries. Chapters 15–18 cover verification, Next.js, security, and migration. Chapters 19–20 synthesize architecture and interview reasoning. Compile examples under strict settings and treat every external value as unknown until validated.',s['body']),PageBreak()]
  for i,item in enumerate(TOPICS,1):story += chapter(item,i,s)
  story += [Paragraph('Final revision checklist',s['chapter']),Paragraph('Before release: strict compilation passes; external inputs are validated; domain states are explicit; DTOs are minimal; server identity drives authorization; repositories hide persistence detail; configuration fails closed; async work is bounded; tests cover negative paths; client bundles contain no secrets; and production claims have runtime evidence.',s['body']),Flow(['STRICT','VALIDATE','MODEL','AUTHORIZE','TEST','OBSERVE'])]
 doc=Doc(str(path),pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,topMargin=20*mm,bottomMargin=22*mm,title='TypeScript Systems Blueprint',author='DevVault',subject='TypeScript architecture study guide');doc.multiBuild(story)

def main():
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,required=True);a=p.parse_args();a.output_dir.mkdir(parents=True,exist_ok=True);full=a.output_dir/'typescript-systems-blueprint-study-guide-v1.pdf';sample=a.output_dir/'typescript-systems-blueprint-public-sample-v1.pdf';build(full);build(sample,True);print({'full':str(full),'sample':str(sample),'chapters':len(TOPICS)})
if __name__=='__main__':main()
